const
    { spawnSync } = require('child_process'),
    pkg           = '@bryntum/schedulerpro-trial-lib',
    script        = `${pkg}/build.js`;
try {
    spawnSync('node', [require.resolve(script)], { cwd : process.cwd(), stdio : 'inherit' });
}
catch (error) {
    console.log(`${pkg} is not installed\n${error.message}`.red);
}
